package com.hongik.grad.users.domain;

import com.hongik.grad.common.jpa.BaseTimeEntity;
import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.time.OffsetDateTime;
import java.util.Locale;
import java.util.UUID;

/**
 * Application user. The PK is a UUID generated by this backend at signup.
 *
 * <p>{@code email} and {@code passwordHash} are nullable: rows created before the move off Supabase
 * Auth have no local credentials and cannot log in.
 */
@Entity
@Table(name = "profiles")
public class Profile extends BaseTimeEntity {

  @Id
  @Column(columnDefinition = "uuid")
  private UUID id;

  @Column(nullable = false, length = 50)
  private String nickname;

  @Column(length = 255)
  private String email;

  @Column(name = "password_hash", length = 100)
  private String passwordHash;

  @Column(name = "deleted_at")
  private OffsetDateTime deletedAt;

  protected Profile() {}

  public Profile(UUID id, String nickname) {
    this.id = id;
    this.nickname = nickname;
  }

  /** Signup factory: generates the PK and stores the already-hashed password. */
  public static Profile signup(String email, String passwordHash, String nickname) {
    Profile profile = new Profile(UUID.randomUUID(), nickname);
    profile.email = normalizeEmail(email);
    profile.passwordHash = passwordHash;
    return profile;
  }

  /** Emails are compared case-insensitively, so they are stored lowercased. */
  public static String normalizeEmail(String email) {
    return email == null ? null : email.trim().toLowerCase(Locale.ROOT);
  }

  public void updateNickname(String nickname) {
    this.nickname = nickname;
  }

  public UUID getId() {
    return id;
  }

  public String getNickname() {
    return nickname;
  }

  public String getEmail() {
    return email;
  }

  public String getPasswordHash() {
    return passwordHash;
  }

  public OffsetDateTime getDeletedAt() {
    return deletedAt;
  }
}
